export const RESEARCH_FORECAST_SYNTHESIS_USER_PROMPT = "请依据下面的已纳入来源预测和样本汇总，生成 Markdown 整理草稿。\n\n固定结构：\n\n## 可比样本概览\n\n按指标和财年说明样本数、口径和范围，只复述输入数字。\n\n## 主要分歧\n\n说明不同来源之间可观察的数值分歧和口径差异，并引用 forecastId。\n\n## 共同驱动与来源观点\n\n只有输入的来源陈述明确包含驱动或观点时才整理；没有就写“待补来源证据”。\n\n## 待人工核验\n\n列出公司/证券身份、币种、会计、归属、每股口径、机构独立性、样本覆盖和其他缺口。\n\n证券代码：{{SECURITY_CODE}}\n经营公司映射状态：{{SUBJECT_STATUS}}\n\n已纳入来源预测：\n{{SOURCE_FORECASTS}}\n\n确定性汇总：\n{{CONSOLIDATION}}";
export const RESEARCH_OPERATING_ANALYSIS_PROMPT = "请对{{SECURITY_NAME}}（{{SECURITY_CODE}}）进行完整的经营与产业研究。先完成检索和证据核验，再开始撰写；不要用已有研报、财报或模型记忆直接填满章节。\n\n研究步骤与来源边界：\n\n1. 以公司法定披露、交易所/监管公告和公司官网作为公司事实基线；它们能确认已披露的产品、财务、订单、资本配置和治理事实，但不能替代行业、竞争或外部变化的验证。\n2. 围绕本公司实际涉及的业务和关键争议，额外检索独立外部证据：可优先使用监管/政府/行业协会数据、上下游或同行公开披露、权威媒体和可回链的研究机构资料。不是每个行业都必须套用相同指标；只寻找与该公司业务边界相关的资料。\n3. 市场空间、行业阶段、供需、竞争、风险、监管变化和外部验证性结论，必须至少有一条独立外部来源；若未找到足以核验的外部证据，明确写“未找到已核验的外部证据”，不能用公司表述或研报观点冒充外部事实。\n4. 先区分证据，再下判断：公司披露写作 `[公司披露]`，独立外部资料写作 `[外部证据]`，由证据推导的结论写作 `[分析判断]`。第三方观点要注明判断主体；来源冲突时并列说明冲突及其对结论的影响，不自行折中。\n5. 每条重要结论、数字或判断旁必须附该条证据的 Markdown 可点击链接，格式如 `[来源名称](https://example.com/source)`；不得只写来源名称、文末笼统列书目或链接到搜索页。没有可回链原文的内容不得写成已验证事实。\n\n以下是系统已经取得的确定性报告期边界，用于区分正式财报与其后的业绩预告或快报；它不是分析材料，也不提供财报链接或三张报表明细。\n{{REPORTING_STATUS_BRIEF}}\n\n以下是系统取得的当前市场快照。它可用于理解市场对公司当前经营的定价起点；直接使用其中价格、市值和 TTM 倍数，不要为了重新确认这些字段而搜索。它们只在所列日期有效，不能替代未来预测、估值假设或每股价值推导。\n\n{{MARKET_SNAPSHOT_BRIEF}}\n\n请用中文输出完整 Markdown 报告（不限制字数），按以下章节：\n\n# 商业模式与赚钱机制\n# 市场空间、产品边界与收入传导\n# 行业阶段、供给约束与竞争\n# 当前增长、驱动与可持续性\n# 利润质量、现金转换与营运资本\n# 资本效率与资本配置\n# 证券定价与反证\n## 当前价格隐含的经营要求\n## 关键估值情景与假设\n## 主报告最可能出错之处与反面证据\n## 投资逻辑失效路径\n## 后续跟踪指标与触发阈值\n\n每个章节按“结论 → 证据与适用期间 → 来源与限制”展开，并让关键结论具备上述来源标记和可点击链接。清楚区分公司披露事实、外部证据和基于证据的判断。管理层计划不得写成已实现，尚未正式披露的业绩预告或快报不得当作正式财报。没有可靠证据时明确未知项，不得编造数字、目标价或交易建议。";
export const RESEARCH_WEB_SEARCH_SOURCE_PACKAGE_SYSTEM_PROMPT = "你是投资研究的信息采集器。你必须使用 Web Search，围绕本次任务的信息目标发现并打开公开可访问资料，再提取与目标直接相关的事实或有明确主体的分析观点。不得编造、补数、用常识推断、把搜索摘要或付费内容目录当作已验证信息。已有结构化来源覆盖的行情、三表、证券身份、13F 和宏观时间序列不得重新搜索或作为主值。同一资料应一次覆盖多个相关字段，不要为每个字段重复搜索。\n\n来源不是任务边界。按信息质量优先使用公司/监管/交易所原文、政府与行业协会资料；当这些资料没有充分解释目标信息时，可以补充公开可访问的券商或研究机构报告、权威媒体报道和对公司或行业专家的公开访谈。第三方判断必须在 statement 中明确写出判断主体，不能伪装成公司事实；关键数字如存在一手来源，应优先采用一手来源。不同来源有冲突时写入 conflicts，不要自行折中。\n\n所有面向用户的文字必须使用简体中文，包括 summary、subject、statement、missing_fields、conflicts 和 refresh_triggers；专有名词、证券代码、字段名、单位和来源原标题可以保留原文。字段名和枚举值使用英文 snake_case。\n\n输出严格 JSON：{summary:string,evidence_records:[{tab_id,field_key,subject,statement,numeric_value,unit,currency,period,product_scope,region_scope,source_title,source_url,source_published_at,status}],missing_fields:string[],conflicts:string[],refresh_triggers:string[]}。status 只能是 verified、unavailable 或 uncited。verified 必须有本次 Web Search 返回的原生 URL citation；source_url 保存该资料的公开链接。uncited 表示模型只有未回链链接或没有链接，不得写成已验证。numeric_value 只能复制来源中的单一数值；没有单一数值时必须为 null。unavailable 必须用中文说明缺失原因。不要输出原文摘录、页码、段落、行号、字符位置、quote 或 locator；不要输出 Markdown 代码块或 JSON 外文字。";
export const RESEARCH_WEB_SEARCH_LATEST_ANNUAL_REPORT_PROMPT = "研究对象：{{SECURITY_CODE}}（{{SECURITY_NAME}}，{{MARKET}}，交易币种 {{CURRENCY}}）\n\n这是“公司经营与结构包”。目标是建立可用于投资分析的公司经营事实与解释框架，覆盖：主营业务与价值链位置、产品/服务及收入结构、客户类型与集中度、地区结构、商业模式、产能/产量/销量/订单、研发与技术路线、资本配置、债务/审计/治理、关键风险，以及公司所处行业边界。\n\n已确认的法定财报边界：{{FINANCIAL_DISCLOSURE_BOUNDARY}}\n已知字段：截至 {{LATEST_FINANCIAL_REPORT_PERIOD}}；发布日期 {{LATEST_FINANCIAL_REPORT_PUBLISHED_AT}}；标题《{{LATEST_FINANCIAL_REPORT_TITLE}}》；原文 {{LATEST_FINANCIAL_REPORT_URL}}。\n先把最新年度报告、20-F 或 10-K 作为公司事实基线；若本地边界是季度报告，不得把它误称为年度报告。年报不是唯一来源：对年报没有披露、表述过于概括或需要外部解释的目标信息，继续搜索公司公告、IR/业绩会、产品资料、监管文件、公开研报、行业机构资料和权威媒体。优先补足有投资价值的缺口，不要为了凑字段重复转述同一事实。\n\n必须区分来源角色：公司和监管材料可作为公司事实；研报、行业资料和媒体中的解释、判断或行业比较必须明确写出判断主体。搜索摘要、无法阅读的付费报告目录和无来源转载不能写成 verified。不同来源的口径或结论冲突时写入 conflicts。\n\nTab 映射必须严格执行：商业模式、产品、客户、地区、产能、订单、研发写 `business`；公司陈述的行业边界、行业需求或竞争对象写 `industry` 或 `market`；资本配置、债务、审计、董事会、独立董事、关联交易、股本和外汇套保等治理事实全部写 `financial`，绝不能输出 `governance`；风险因素和触发器写 `risk`。\n\nevidence_records[].tab_id 仅可为：{{TAB_IDS}}。字段名和枚举值使用英文 snake_case；不得输出中文 Tab 名称。除字段名、枚举值、证券代码、单位和来源原标题外，所有输出内容使用简体中文。";
export const RESEARCH_WEB_SEARCH_RECENT_FILINGS_PROMPT = "研究对象：{{SECURITY_CODE}}（{{SECURITY_NAME}}，{{MARKET}}，交易币种 {{CURRENCY}}）\n\n这是“经营变化包”。目标是找出相对既有财报基线真正新增或发生变化的信息：经营趋势、产品进展、客户/订单、产能、管理层指引、重大合同、融资、回购、审批、催化剂和风险。重点搜索财报边界之后及最近十二个月的信息，但不要把来源形式限定为公告。\n\n已确认的法定财报边界：{{FINANCIAL_DISCLOSURE_BOUNDARY}}\n已知字段：截至 {{LATEST_FINANCIAL_REPORT_PERIOD}}；发布日期 {{LATEST_FINANCIAL_REPORT_PUBLISHED_AT}}；标题《{{LATEST_FINANCIAL_REPORT_TITLE}}》；原文 {{LATEST_FINANCIAL_REPORT_URL}}。\n每条记录必须能说明“相对该边界的新变化”、发生或披露日期，以及它是已发生事实、管理层指引还是待触发事件。公司结构化三表数值不是本包主值。优先使用公司、交易所和监管材料；当一手材料没有解释变化原因或行业影响时，可以补充公开研报、行业机构资料和权威媒体，但必须明确判断主体，不能把第三方解释写成公司事实。\n\n同一资料一次提取多个字段。evidence_records[].tab_id 仅可为：{{TAB_IDS}}。字段名和枚举值使用英文 snake_case；不得输出中文 Tab 名称。除字段名、枚举值、证券代码、单位和来源原标题外，所有输出内容使用简体中文。";
export const RESEARCH_WEB_SEARCH_INDUSTRY_MARKET_PROMPT = "研究对象：{{SECURITY_CODE}}（{{SECURITY_NAME}}，{{MARKET}}，交易币种 {{CURRENCY}}）\n\n这是“行业与市场空间包”。目标是围绕公司明确主营的二级赛道，获取行业定义、市场规模、需求、供给、价格、出货、库存、产能、产品结构、增长和公司可服务边界。先用已有公司资料识别产品、地区和客户边界；年报、公告、IR、公开研报、政府/协会资料、产业链披露和权威媒体都可以服务这一目标，不按文档类型限制搜索。公司收入绝不能直接当成行业市场规模或 TAM 的分母。\n\nTAM：只记录公开原文直接给出的市场规模，或原文明确给出的可复算输入；每条必须保留产品、地区、客户、期间、收入/出货/数量和预测/实际口径。不要把不同产品、地区、期间或收入/出货口径混成一个 TAM，不要把付费报告目录或搜索摘要写成已验证数值。\n若公开页只说明某数据库/报告“覆盖”出货量、价格或销售额，却没有展示该指标的实际数值、期间和边界，该指标必须标记 `unavailable`；不得把目录或覆盖描述写成 `verified` 的出货量、价格、TAM 或份额事实。\nSAM：只能记录可服务边界的公开事实，例如公司实际产品/地区、客户类型、认证、监管、渠道、交付或相邻子市场。除非原文直接披露公司可服务市场，不得把相邻子市场或模型推断标为“公司 SAM”。\nSOM/份额：只记录同口径公司分子与行业分母，或记录可用于后续程序计算的单独输入；不得自行计算或把不同边界强行相除。缺 ASP、分速率出货、产品收入拆分或排重信息时，应写 unavailable/缺口。\n\n优先使用政府、统计部门、行业协会和公司披露；公开研报或权威媒体的行业分析可以补充，但必须注明判断主体和统计口径。搜索摘要或付费报告目录只能标记 unavailable。evidence_records[].tab_id 仅可为：{{TAB_IDS}}。字段名和枚举值使用英文 snake_case；不得输出中文 Tab 名称。除字段名、枚举值、证券代码、单位和来源原标题外，所有输出内容使用简体中文。";
export const RESEARCH_WEB_SEARCH_PEER_SET_PROMPT = "研究对象：{{SECURITY_CODE}}（{{SECURITY_NAME}}，{{MARKET}}，交易币种 {{CURRENCY}}）\n\n这是“同行与竞争包”。目标是确认真正可比的同行，并获取产品/服务边界、地区、客户、技术路线、产能/出货、竞争位置、战略动作和可比性限制。可以使用目标公司与同行的年报、公告、IR、产品资料、公开研报、行业机构资料和权威媒体，不按文档类型限制搜索；不能只从公司名称、单一无来源报道或模型常识推定竞争关系。\n不要把不同产品、地区、期间或收入/出货单位的同行指标直接并列成份额、排名或优劣结论；边界不一致时单独记录限制或 unavailable。\n\n公司自述、第三方比较和模型整理必须分开表述；第三方排名或优劣判断必须明确判断主体。evidence_records[].tab_id 仅可为：{{TAB_IDS}}。字段名和枚举值使用英文 snake_case；不得输出中文 Tab 名称。除字段名、枚举值、证券代码、单位和来源原标题外，所有输出内容使用简体中文。";
export const RESEARCH_WEB_SEARCH_FORECAST_CONSENSUS_PROMPT = "研究对象：{{SECURITY_CODE}}（{{SECURITY_NAME}}，{{MARKET}}，交易币种 {{CURRENCY}}）\n\n这是“外部预测补充包”，只在用户明确需要项目内部研报预测账本之外的内容时使用。项目内账本覆盖情况：{{INTERNAL_FORECAST_COVERAGE}}\n\n不要搜索、重建或替代项目内已有研报预测，也不要把 Web Search 结果与其拼成“市场一致预期”。公司管理层指引仍由经营变化包处理。本包只围绕内部未覆盖的前瞻信息目标补充资料，例如行业规模、需求/出货/价格展望和产业链公司的明确预测。可以使用公开可访问的研究报告、行业协会、官方机构、公司材料和权威媒体；每条必须保留预测主体、发布时间、目标期间、指标、币种/单位、统计/会计口径及修订信息（如来源有）。\n\n本地已知财报截至 {{LATEST_FINANCIAL_REPORT_PERIOD}}、发布日期 {{LATEST_FINANCIAL_REPORT_PUBLISHED_AT}}，仅用于区分已披露实际业绩与未来预测；不需要打开或引用该财报链接。区间、条件性表述或口径不完整时保留原文限制，不补成单点数字。没有授权的完整样本时，绝不能称为市场一致预期或市场共识。\n\nevidence_records[].tab_id 仅可为：{{TAB_IDS}}。字段名和枚举值使用英文 snake_case；不得输出中文 Tab 名称。除字段名、枚举值、证券代码、单位和来源原标题外，所有输出内容使用简体中文。";
